import{_ as p,a0 as o,w as r,s as d,I as i,x as a,a1 as e,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"LXD 2.0 系列（六）：遠程主機及容器遷移 | LCTT x X-CMD","titleTemplate":false,"description":"LXD 2.0 系列（六）：遠程主機及容器遷移 | LCTT (LXD) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LXD 2.0 系列（六）：遠程主機及容器遷移 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LXD 2.0 系列（六）：遠程主機及容器遷移 | LCTT (LXD) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LXD/Part 6 - LXD 2.0--Remote hosts and container migration","title":"LXD 2.0 系列（六）：遠程主機及容器遷移","tag":"LXD","desc":""},"relativePath":"LXD/Part 6 - LXD 2.0--Remote hosts and container migration.md","filePath":"[post].md"}'),h={name:"LXD/Part 6 - LXD 2.0--Remote hosts and container migration.md"};function g(c,s,b,u,f,k){const n=o("Link");return r(),d("div",null,[s[28]||(s[28]=i("h1",{id:"lxd-2-0-系列-六-遠程主機及容器遷移",tabindex:"-1"},[a("LXD 2.0 系列（六）：遠程主機及容器遷移 "),i("a",{class:"header-anchor",href:"#lxd-2-0-系列-六-遠程主機及容器遷移","aria-label":"Permalink to “LXD 2.0 系列（六）：遠程主機及容器遷移”"},"​")],-1)),i("p",null,[s[1]||(s[1]=a("這是 ",-1)),e(n,{href:"https://www.stgraber.org/2016/03/11/lxd-2-0-blog-post-series-012/"},{default:t(()=>[...s[0]||(s[0]=[a("LXD 2.0 系列介紹文章",-1)])]),_:1}),s[2]||(s[2]=a("的第六篇。",-1))]),s[29]||(s[29]=l('<p><img src="https://linuxcontainers.org/static/img/containers.png" alt=""></p><h3 id="遠程協議" tabindex="-1">遠程協議 <a class="header-anchor" href="#遠程協議" aria-label="Permalink to “遠程協議”">​</a></h3><p>LXD 2.0 支持兩種協議:</p><ul><li>LXD 1.0 API：這是在客户端和 LXD 守護進程之間使用的 REST API，以及在 LXD 守護進程間複製/移動鏡像和容器時使用的 REST API。</li><li>Simplestreams：Simplestreams 協議是 LXD 客户端和守護進程使用的只讀、僅針對鏡像的協議，用於客户端和 LXD 守護進程獲取鏡像信息以及從一些公共鏡像服務器（如 Ubuntu 鏡像）導入鏡像。</li></ul><p>以下所有內容都將使用這兩個協議中的第一個。</p><h3 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h3><p>LXD API 的驗證是通過客户端證書在 TLS 1.2 上使用最近的密鑰驗證的。 當兩個 LXD 守護進程必須直接交換信息時，源守護程序生成一個臨時令牌，並通過客户端傳輸到目標守護程序。 此令牌僅可用於訪問特定流，並且會被立即撤銷，因此不能重新使用。</p><p>為了避免中間人攻擊，客户端工具還將源服務器的證書發送到目標服務器。這意味着對於特定的下載操作，目標服務器會被提供源服務器的 URL、所需資源的一次性訪問令牌以及服務器應該使用的證書。 這可以防止中間人攻擊，並且只允許臨時訪問所傳輸的對象。</p><h3 id="網絡需求" tabindex="-1">網絡需求 <a class="header-anchor" href="#網絡需求" aria-label="Permalink to “網絡需求”">​</a></h3><p>LXD 2.0 使用這樣一種模型，某個操作的目標（接收端）直接連接到源以獲取數據。</p><p>這意味着你必須確保目標服務器可以直接連接到源、可以更新任何所需的防火牆。</p>',11)),i("p",null,[s[4]||(s[4]=a("我們有個",-1)),e(n,{href:"https://github.com/lxc/lxd/issues/553"},{default:t(()=>[...s[3]||(s[3]=[a("允許反向連接的計劃",-1)])]),_:1}),s[5]||(s[5]=a("，允許通過客户端代理本身以應對那些嚴格的防火牆阻止兩台主機之間通信的罕見情況。",-1))]),s[30]||(s[30]=l(`<h3 id="與遠程主機交互" tabindex="-1">與遠程主機交互 <a class="header-anchor" href="#與遠程主機交互" aria-label="Permalink to “與遠程主機交互”">​</a></h3><p>LXD 使用的是“遠程”的概念，而不是讓我們的用户總是提供主機名或 IP 地址，然後在他們想要與遠程主機交互時驗證證書信息。</p><p>默認情況下，唯一真正的 LXD 遠程配置是 <code>local:</code>，這也是默認的遠程（所以你不必輸入它的名稱）。這個本地（<code>local:</code>）遠程使用 LXD REST API 通過 unix 套接字與本地守護進程通信。</p><h4 id="添加一台遠程主機" tabindex="-1">添加一台遠程主機 <a class="header-anchor" href="#添加一台遠程主機" aria-label="Permalink to “添加一台遠程主機”">​</a></h4><p>假設你已經有兩台裝有 LXD 的機器：你的本機以及遠程那台我們稱為“foo”的主機。</p><p>首先你需要確保“foo”正在監聽網絡，並設置了一個密碼，以便得到一個遠程 shell，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc config set core.https_address [::]:8443</span></span>
<span class="line"><span>lxc config set core.trust_password something-secure</span></span></code></pre></div><p>在你本地 LXD 上，你需要使它對網絡可見，這樣我們可以從它傳輸容器和鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc config set core.https_address [::]:8443</span></span></code></pre></div><p>現在已經在兩端完成了守護進程的配置，你可以添加“foo”到你的本地客户端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc remote add foo 1.2.3.4</span></span></code></pre></div><p>（將 1.2.3.4 替換成你的 IP 或者 FQDN）</p><p>看上去像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@dakara:~$ lxc remote add foo 2607:f2c0:f00f:2770:216:3eff:fee1:bd67</span></span>
<span class="line"><span>Certificate fingerprint: fdb06d909b77a5311d7437cabb6c203374462b907f3923cefc91dd5fce8d7b60</span></span>
<span class="line"><span>ok (y/n)? y</span></span>
<span class="line"><span>Admin password for foo: </span></span>
<span class="line"><span>Client certificate stored at server: foo</span></span></code></pre></div><p>你接着可以列出遠端服務器，你可以在列表中看到“foo”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@dakara:~$ lxc remote list</span></span>
<span class="line"><span>+-----------------+-------------------------------------------------------+---------------+--------+--------+</span></span>
<span class="line"><span>|      NAME       |                         URL                           |   PROTOCOL    | PUBLIC | STATIC |</span></span>
<span class="line"><span>+-----------------+-------------------------------------------------------+---------------+--------+--------+</span></span>
<span class="line"><span>| foo             | https://[2607:f2c0:f00f:2770:216:3eff:fee1:bd67]:8443 | lxd           | NO     | NO     |</span></span>
<span class="line"><span>+-----------------+-------------------------------------------------------+---------------+--------+--------+</span></span>
<span class="line"><span>| images          | https://images.linuxcontainers.org:8443               | lxd           | YES    | NO     |</span></span>
<span class="line"><span>+-----------------+-------------------------------------------------------+---------------+--------+--------+</span></span>
<span class="line"><span>| local (default) | unix://                                               | lxd           | NO     | YES    |</span></span>
<span class="line"><span>+-----------------+-------------------------------------------------------+---------------+--------+--------+</span></span>
<span class="line"><span>| ubuntu          | https://cloud-images.ubuntu.com/releases              | simplestreams | YES    | YES    |</span></span>
<span class="line"><span>+-----------------+-------------------------------------------------------+---------------+--------+--------+</span></span>
<span class="line"><span>| ubuntu-daily    | https://cloud-images.ubuntu.com/daily                 | simplestreams | YES    | YES    |</span></span>
<span class="line"><span>+-----------------+-------------------------------------------------------+---------------+--------+--------+</span></span></code></pre></div><h4 id="與它交互" tabindex="-1">與它交互 <a class="header-anchor" href="#與它交互" aria-label="Permalink to “與它交互”">​</a></h4><p>好了，所以我們已經有了一台定義好的遠程服務器，我們現在可以做些什麼？</p><p>現在，就如你看到的，唯一的不同是你必須告訴 LXD 要哪台主機運行。</p><p>比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc launch ubuntu:14.04 c1</span></span></code></pre></div><p>它會在默認主機（<code>lxc remote get-default</code>），也就是你的本機上運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc launch ubuntu:14.04 foo:c1</span></span></code></pre></div><p>這個會在 foo 上運行。</p><p>列出遠程主機正在運行的容器可以這麼做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@dakara:~$ lxc list foo:</span></span>
<span class="line"><span>+------+---------+---------------------+-----------------------------------------------+------------+-----------+</span></span>
<span class="line"><span>| NAME |  STATE  |         IPV4        |                     IPV6                      |    TYPE    | SNAPSHOTS |</span></span>
<span class="line"><span>+------+---------+---------------------+-----------------------------------------------+------------+-----------+</span></span>
<span class="line"><span>| c1   | RUNNING | 10.245.81.95 (eth0) | 2607:f2c0:f00f:2770:216:3eff:fe43:7994 (eth0) | PERSISTENT | 0         |</span></span>
<span class="line"><span>+------+---------+---------------------+-----------------------------------------------+------------+-----------+</span></span></code></pre></div><p>你要記住的一件事是你需要在遠程主機上同時指定鏡像和容器。因此如果你在“foo”上有一個“my-image”的鏡像，並且希望從它創建一個“c2”的容器，你需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc launch foo:my-image foo:c2</span></span></code></pre></div><p>最後，就如你希望的那樣得到一個遠程容器的 shell：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc exec foo:c1 bash</span></span></code></pre></div><h4 id="複製容器" tabindex="-1">複製容器 <a class="header-anchor" href="#複製容器" aria-label="Permalink to “複製容器”">​</a></h4><p>在兩台主機間複製容器就如它聽上去那樣簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc copy foo:c1 c2</span></span></code></pre></div><p>你會有一個新的從遠程“c1”複製過來的本地“c2”容器。這需要停止“c1”容器，但是你可以在運行的時候只複製一個快照：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc snapshot foo:c1 current</span></span>
<span class="line"><span>lxc copy foo:c1/current c3</span></span></code></pre></div><h4 id="移動容器" tabindex="-1">移動容器 <a class="header-anchor" href="#移動容器" aria-label="Permalink to “移動容器”">​</a></h4><p>除非你在做實時遷移（將會在之後的文章中講到），不然你需要在移動前先停止容器，接着就會如你預料的那樣。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc stop foo:c1</span></span>
<span class="line"><span>lxc move foo:c1 local:</span></span></code></pre></div><p>這個例子等同於：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxc stop foo:c1</span></span>
<span class="line"><span>lxc move foo:c1 c1</span></span></code></pre></div><h3 id="這些如何工作" tabindex="-1">這些如何工作 <a class="header-anchor" href="#這些如何工作" aria-label="Permalink to “這些如何工作”">​</a></h3><p>正如你期望的那樣, 與遠程容器的交互時 LXD 使用的 REST API 並不是通過本地 Unix 套接字，而是通過 HTTPS 傳輸。</p><p>當兩個守護程序之間交互時會變得有些棘手，如複製和移動的情況。</p><p>在這種情況下會發生：</p><ol><li>用户運行<code>lxc move foo：c1 c1</code>。</li><li>客户端聯繫 <code>local:</code> 遠程以檢查是否現有“c1”容器。</li><li>客户端從“foo”獲取容器信息。</li><li>客户端從源“foo”守護程序請求遷移令牌。</li><li>客户端將遷移令牌以及源 URL 和“foo”的證書發送到本地 LXD 守護程序以及容器配置和周圍設備。</li><li>然後本地 LXD 守護程序使用提供的令牌直接連接到“foo” a) 它連接到第一個控制 websocket    b) 它協商文件系統傳輸協議（zfs 發送/接收，btrfs 發送/接收或者純 rsync）    c) 如果在本地可用，它會解壓用於創建源容器的鏡像。這是為了避免不必要的數據傳輸。    d) 然後它會將容器及其任何快照作為增量傳輸。</li><li>如果成功，客户端會命令“foo”刪除源容器。</li></ol><h3 id="在線嘗試" tabindex="-1">在線嘗試 <a class="header-anchor" href="#在線嘗試" aria-label="Permalink to “在線嘗試”">​</a></h3><p>沒有兩台機器來嘗試遠端交互和複製/移動容器？</p>`,47)),i("p",null,[s[7]||(s[7]=a("沒有問題，你可以使用我們的 ",-1)),e(n,{href:"https://linuxcontainers.org/lxd/try-it/"},{default:t(()=>[...s[6]||(s[6]=[a("demo 服務",-1)])]),_:1}),s[8]||(s[8]=a("。這裏甚至還包括了一步步的指導！",-1))]),s[31]||(s[31]=i("h3",{id:"額外信息",tabindex:"-1"},[a("額外信息 "),i("a",{class:"header-anchor",href:"#額外信息","aria-label":"Permalink to “額外信息”"},"​")],-1)),i("p",null,[s[10]||(s[10]=a("LXD 的主站在: ",-1)),e(n,{href:"https://linuxcontainers.org/lxd"},{default:t(()=>[...s[9]||(s[9]=[a("https://linuxcontainers.org/lxd",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("LXD 的 GitHub 倉庫: ",-1)),e(n,{href:"https://github.com/lxc/lxd"},{default:t(()=>[...s[11]||(s[11]=[a("https://github.com/lxc/lxd",-1)])]),_:1})]),i("p",null,[s[14]||(s[14]=a("LXD 的郵件列表: ",-1)),e(n,{href:"https://lists.linuxcontainers.org"},{default:t(()=>[...s[13]||(s[13]=[a("https://lists.linuxcontainers.org",-1)])]),_:1})]),s[32]||(s[32]=i("p",null,"LXD 的 IRC 頻道: #lxcontainers on irc.freenode.net",-1)),s[33]||(s[33]=i("hr",null,null,-1)),i("p",null,[s[16]||(s[16]=a("via: ",-1)),e(n,{href:"https://www.stgraber.org/2016/04/12/lxd-2-0-remote-hosts-and-container-migration-612/"},{default:t(()=>[...s[15]||(s[15]=[a("https://www.stgraber.org/2016/04/12/lxd-2-0-remote-hosts-and-container-migration-612/",-1)])]),_:1})]),i("p",null,[s[20]||(s[20]=a("作者：",-1)),e(n,{href:"https://www.stgraber.org/author/stgraber/"},{default:t(()=>[...s[17]||(s[17]=[a("Stéphane Graber",-1)])]),_:1}),s[21]||(s[21]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[18]||(s[18]=[a("geekpi",-1)])]),_:1}),s[22]||(s[22]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[19]||(s[19]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[25]||(s[25]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[23]||(s[23]=[a("LCTT",-1)])]),_:1}),s[26]||(s[26]=a(" 組織翻譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[24]||(s[24]=[a("Linux中國",-1)])]),_:1}),s[27]||(s[27]=a(" 榮譽推出",-1))])])}const y=p(h,[["render",g]]);export{L as __pageData,y as default};
